local _, ns = ...

--[[
    Berechnete Talentverteilungen (Welle 21, docs/talent-simulation.md). Diese Datei schreibt das Werkzeug
    tools/talent_sim.lua – nicht von Hand ändern:
        luajit tools/talent_sim.lua [<Messung je Klasse …>] --wago --aus=ezTalent/Computed.lua

    Grundlage (Leitlinie 11): die Talentbäume aus den Client-Tabellen (tools/daten/wago/talente.lua, laut wago.tools)
    bzw. die Messung „Werte für die Simulation messen“ je Klasse aus dem Client (ezTalent) und das Rechenmodell des
    Werkzeugs (Wertgewichte je Spielweise, allgemeine Spielmechanik mit Quelle in docs/talent-simulation.md). Nichts
    aus fremden Addons, Simulatoren oder Ratgebern (Leitlinie 10). Die Quelle je Verteilung steht in computed.values.
    Form eines Eintrags wie die Vorauswahl (Presets.lua) mit grade = "computed", computed = { … } und der Kennung
    am Talent (spell, row, col). Feld 3 eines Talents: englischer Name (aus einer englischen Messung bzw. PresetIDs.lua),
    sonst der Name im Client der Messung; Feld 4: Name im deutschen Client (laut wago.tools, SpellName deDE, bzw. aus
    einer deDE-Messung). computed.provisional = true: vorläufig, Grundwerte geschätzt (noch ohne Messung im Spiel).
    Rechenmodell 3: style = { key (raid, dungeon, solo, pvp, survival, ranged, pet, weapon), role (damage, tank,
    healer), range (melee, ranged, caster), weapon, form, pet (nur wenn festgelegt), label = { de, en } } für den
    Fragebogen; computed.parts = { damage, survival, utility } in der Form von computed.weights (Summe = weights);
    computed.gear = { weights (Wert je Punkt eines Gegenstandswerts, Schlüssel wie ezGear, Hauptwert 1), weapon,
    weapons, source } für ezGear (Sim.Gear, Annahmen im Kopf von tools/talent_sim.lua);
    ns.COMPUTED_RACES = passive Volkswerte laut Client-Tabellen (SkillLine Kategorie 9, SkillLineAbility,
    SpellEffect; mit --roh=<Rohordner>) samt Hinweis text.de/text.en – die Verteilungen rechnen ohne Volk.
]]

